/bin/bash -lc "/opt/conda/bin/pvpython - <<'PY'
from paraview.simple import *
r=XMLImageDataReader(FileName=['/workspace/QMCPACK.vti'])
d=TTKPersistenceDiagram(Input=r)
for propname in ['Dimensions','ScalarField']:
 p=d.GetProperty(propname)
 print(propname,p, p.GetNumberOfDomains())
 for i in range(p.GetNumberOfDomains()):
  dom=p.GetDomain(i); print(' dom',dom, dom.GetClassName())
  for j in range(10):
   try: print(j,dom.GetEntryText(j),dom.GetEntryValue(j))
   except: break
PY"

